reference_solution:
def valid_wildcard_parentheses(s):
    low = high = 0
    for char in s:
        if char == '(':
            low += 1; high += 1
        elif char == ')':
            low = max(0, low - 1); high -= 1
        else:
            low = max(0, low - 1); high += 1
        if high < 0: return False
    return low == 0

